1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUM_RATES: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const CURSE_SURCHARGE_RATE = 0.5;
55	const COMPONENT_BLOCK_SIZE = 3;
56	const COMPONENT_BLOCK_PREMIUM = 60;
57	
58	const countByType = (items: Item[]): Map<string, number> =>
59	  items.reduce(
60	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
61	    new Map<string, number>(),
62	  );
63	
64	const basePremiumForGroup = (type: string, itemCount: number): number =>
65	  itemCount === COMPONENT_BLOCK_SIZE
66	    ? COMPONENT_BLOCK_PREMIUM
67	    : itemCount * BASE_PREMIUM_RATES[type];
68	
69	const sumBasePremiums = (items: Item[]): number =>
70	  [...countByType(items)].reduce(
71	    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
72	    0,
73	  );
74	
75	const sumItemSurcharges = (items: Item[]): number =>
76	  items.reduce(
77	    (sum, item) =>
78	      sum + (item.cursed ? BASE_PREMIUM_RATES[item.type] * CURSE_SURCHARGE_RATE : 0),
79	    0,
80	  );
81	
82	const quote = (items: Item[]): StepResult => {
83	  const basePremium = sumBasePremiums(items);
84	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
85	
86	  return {
87	    premium: Math.ceil(
88	      basePremium +
89	        sumItemSurcharges(items) +
90	        firstInsuranceSurcharge +
91	        PROCESSING_FEE,
92	    ),
93	  };
94	};
95	
96	const runStep = (step: Step): StepResult => {
97	  switch (step.op) {
98	    case "quote":
99	      return quote(step.items);
100	    default:
101	      throw new Error(`Unsupported step: ${step.op}`);
102	  }
103	};
104	
105	export const runScenario = (scenario: Scenario): ScenarioResult => ({
106	  results: scenario.steps.map(runStep),
107	});
